import sys, json
from typing import List

class Solution:
    def generateSentences(self, synonyms: List[List[str]], text: str) -> List[str]:
        parent = {}

        def add(word: str) -> None:
            if word not in parent:
                parent[word] = word

        def find(word: str) -> str:
            root = word
            while parent[root] != root:
                root = parent[root]
            while parent[word] != word:
                nxt = parent[word]
                parent[word] = root
                word = nxt
            return root

        for a, b in synonyms:
            add(a)
            add(b)
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra

        groups = {}
        for word in parent:
            root = find(word)
            groups.setdefault(root, []).append(word)
        for words in groups.values():
            words.sort()

        options = []
        for word in text.split(" "):
            if word in parent:
                options.append(groups[find(word)])
            else:
                options.append([word])

        result = []
        path = []

        def dfs(index: int) -> None:
            if index == len(options):
                result.append(" ".join(path))
                return
            for choice in options[index]:
                path.append(choice)
                dfs(index + 1)
                path.pop()

        dfs(0)
        result.sort()
        return result

