#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_WORDS 20
#define MAX_TOKENS 21
#define MAX_WORD_LEN 11
#define MAX_TEXT_WORDS 10
#define MAX_SENTENCE_LEN 128

static char quoted[MAX_TOKENS][MAX_SENTENCE_LEN];
static int quoted_count = 0;

static char words[MAX_WORDS][MAX_WORD_LEN];
static int word_count = 0;
static int parent[MAX_WORDS];

static char text_words[MAX_TEXT_WORDS][MAX_WORD_LEN];
static int text_word_count = 0;

static char** results = NULL;
static int result_count = 0;
static int result_capacity = 0;

static int find_root(int x) {
    if (parent[x] == x) return x;
    parent[x] = find_root(parent[x]);
    return parent[x];
}

static int find_word(const char* word) {
    for (int i = 0; i < word_count; ++i) {
        if (strcmp(words[i], word) == 0) return i;
    }
    return -1;
}

static int add_word(const char* word) {
    int id = find_word(word);
    if (id >= 0) return id;

    id = word_count++;
    strcpy(words[id], word);
    parent[id] = id;
    return id;
}

static void union_words(int a, int b) {
    int ra = find_root(a);
    int rb = find_root(b);
    if (ra != rb) parent[rb] = ra;
}

static void extract_quoted_strings(const char* line) {
    int in_string = 0;
    int len = 0;

    for (int i = 0; line[i] != '\0'; ++i) {
        char c = line[i];

        if (c == '"') {
            if (in_string) {
                quoted[quoted_count][len] = '\0';
                ++quoted_count;
                len = 0;
                in_string = 0;
            } else {
                in_string = 1;
            }
        } else if (in_string) {
            if (len < MAX_SENTENCE_LEN - 1) {
                quoted[quoted_count][len++] = c;
            }
        }
    }
}

static void parse_text_words(const char* text) {
    char buffer[MAX_SENTENCE_LEN];
    strcpy(buffer, text);

    char* token = strtok(buffer, " ");
    while (token != NULL && text_word_count < MAX_TEXT_WORDS) {
        strcpy(text_words[text_word_count++], token);
        token = strtok(NULL, " ");
    }
}

static void ensure_result_capacity(void) {
    if (result_count < result_capacity) return;

    int new_capacity = (result_capacity == 0) ? 16 : result_capacity * 2;
    char** next = (char**)realloc(results, (size_t)new_capacity * sizeof(char*));
    if (next == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }

    results = next;
    result_capacity = new_capacity;
}

static void append_choice(char* buffer, int* length, const char* word, int position) {
    if (position > 0) {
        buffer[(*length)++] = ' ';
    }
    int wlen = (int)strlen(word);
    memcpy(buffer + *length, word, (size_t)wlen);
    *length += wlen;
    buffer[*length] = '\0';
}

static void backtrack(int pos, char* buffer, int length) {
    if (pos == text_word_count) {
        ensure_result_capacity();
        results[result_count] = (char*)malloc((size_t)MAX_SENTENCE_LEN);
        if (results[result_count] == NULL) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
        strcpy(results[result_count], buffer);
        ++result_count;
        return;
    }

    int id = find_word(text_words[pos]);

    if (id < 0) {
        int next_length = length;
        append_choice(buffer, &next_length, text_words[pos], pos);
        backtrack(pos + 1, buffer, next_length);
        return;
    }

    int root = find_root(id);
    for (int i = 0; i < word_count; ++i) {
        if (find_root(i) == root) {
            int next_length = length;
            append_choice(buffer, &next_length, words[i], pos);
            backtrack(pos + 1, buffer, next_length);
        }
    }
}

static int compare_strings(const void* a, const void* b) {
    const char* sa = *(const char* const*)a;
    const char* sb = *(const char* const*)b;
    return strcmp(sa, sb);
}

int main(void) {
    char line[4096];

    if (!fgets(line, sizeof(line), stdin)) {
        return 0;
    }

    extract_quoted_strings(line);

    int pair_count = (quoted_count - 1) / 2;

    for (int i = 0; i < pair_count; ++i) {
        int a = add_word(quoted[2 * i]);
        int b = add_word(quoted[2 * i + 1]);
        union_words(a, b);
    }

    parse_text_words(quoted[quoted_count - 1]);

    char buffer[MAX_SENTENCE_LEN] = "";
    backtrack(0, buffer, 0);

    qsort(results, (size_t)result_count, sizeof(results[0]), compare_strings);

    printf("[");
    for (int i = 0; i < result_count; ++i) {
        if (i > 0) printf(",");
        printf("\"%s\"", results[i]);
    }
    printf("]\n");

    for (int i = 0; i < result_count; ++i) {
        free(results[i]);
    }
    free(results);

    return 0;
}

