using namespace std;

class Solution {
    unordered_map<string, int> id;
    vector<string> words;
    vector<int> parent;

    int find(int x) {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a != b) parent[b] = a;
    }

public:
    vector<string> generateSentences(vector<vector<string>>& synonyms, string text) {
        auto getId = [&](const string& word) -> int {
            auto it = id.find(word);
            if (it != id.end()) return it->second;
            int idx = (int)words.size();
            id[word] = idx;
            words.push_back(word);
            parent.push_back(idx);
            return idx;
        };

        for (const auto& pair : synonyms) {
            int a = getId(pair[0]);
            int b = getId(pair[1]);
            unite(a, b);
        }

        unordered_map<int, vector<string>> groups;
        for (int i = 0; i < (int)words.size(); ++i) {
            groups[find(i)].push_back(words[i]);
        }
        for (auto& entry : groups) sort(entry.second.begin(), entry.second.end());

        vector<string> sentence;
        string word;
        stringstream ss(text);
        while (ss >> word) sentence.push_back(word);

        vector<vector<string>> options;
        for (const string& w : sentence) {
            auto it = id.find(w);
            if (it == id.end()) {
                options.push_back({w});
            } else {
                options.push_back(groups[find(it->second)]);
            }
        }

        vector<string> result;
        vector<string> path;

        function<void(int)> dfs = [&](int index) {
            if (index == (int)options.size()) {
                string current;
                for (int i = 0; i < (int)path.size(); ++i) {
                    if (i) current += ' ';
                    current += path[i];
                }
                result.push_back(current);
                return;
            }

            for (const string& choice : options[index]) {
                path.push_back(choice);
                dfs(index + 1);
                path.pop_back();
            }
        };

        dfs(0);
        sort(result.begin(), result.end());
        return result;
    }
};

static vector<string> extractQuotedStrings(const string& line) {
