import java.io.*;
import java.util.*;
import java.util.regex.*;

class Solution {
    private final Map<String, String> parent = new HashMap<>();

    private void add(String word) {
        parent.putIfAbsent(word, word);
    }

    private String find(String word) {
        String root = word;
        while (!parent.get(root).equals(root)) {
            root = parent.get(root);
        }
        while (!parent.get(word).equals(word)) {
            String next = parent.get(word);
            parent.put(word, root);
            word = next;
        }
        return root;
    }

    public List<String> generateSentences(List<List<String>> synonyms, String text) {
        for (List<String> pair : synonyms) {
            String a = pair.get(0);
            String b = pair.get(1);
            add(a);
            add(b);
            String ra = find(a);
            String rb = find(b);
            if (!ra.equals(rb)) {
                parent.put(rb, ra);
            }
        }

        Map<String, List<String>> groups = new HashMap<>();
        for (String word : parent.keySet()) {
            String root = find(word);
            groups.computeIfAbsent(root, k -> new ArrayList<>()).add(word);
        }
        for (List<String> words : groups.values()) {
            Collections.sort(words);
        }

        String[] sentence = text.split(" ");
        List<List<String>> options = new ArrayList<>();
        for (String word : sentence) {
            if (parent.containsKey(word)) {
                options.add(groups.get(find(word)));
            } else {
                options.add(Collections.singletonList(word));
            }
        }

        List<String> result = new ArrayList<>();
        backtrack(0, options, new ArrayList<>(), result);
        Collections.sort(result);
        return result;
    }

    private void backtrack(int index, List<List<String>> options, List<String> path, List<String> result) {
        if (index == options.size()) {
            result.add(String.join(" ", path));
            return;
        }
        for (String choice : options.get(index)) {
            path.add(choice);
            backtrack(index + 1, options, path, result);
            path.remove(path.size() - 1);
        }
    }
}

public class Main {
    private static List<String> extractQuotedStrings(String line) {
        List<String> values = new ArrayList<>();
        boolean inString = false;
        StringBuilder current = new StringBuilder();

        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c == '"') {
                if (inString) {
                    values.add(current.toString());
                    current.setLength(0);
                    inString = false;
                } else {
                    inString = true;
                }
            } else if (inString) {
                current.append(c);
            }
        }
        return values;
    }

    private static String jsonString(String s) {
        return "\"" + s.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
    }

    private static String jsonArray(List<String> values) {
        StringBuilder out = new StringBuilder("[");
        for (int i = 0; i < values.size(); i++) {
            if (i > 0) out.append(',');
            out.append(jsonString(values.get(i)));
        }
        return out.append(']').toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        List<String> q = extractQuotedStrings(line);

        int pairCount = (q.size() - 1) / 2;
        List<List<String>> synonyms = new ArrayList<>();
        for (int i = 0; i < pairCount; i++) {
            synonyms.add(Arrays.asList(q.get(2 * i), q.get(2 * i + 1)));
        }
        String text = q.get(q.size() - 1);

        List<String> result = new Solution().generateSentences(synonyms, text);
        System.out.println(jsonArray(result));
    }
}

