const readline = require("readline");

function generateSentences(synonyms, text) {
    const parent = new Map();

    function add(word) {
        if (!parent.has(word)) parent.set(word, word);
    }

    function find(word) {
        let root = word;
        while (parent.get(root) !== root) root = parent.get(root);
        while (parent.get(word) !== word) {
            const next = parent.get(word);
            parent.set(word, root);
            word = next;
        }
        return root;
    }

    for (const [a, b] of synonyms) {
        add(a);
        add(b);
        const ra = find(a);
        const rb = find(b);
        if (ra !== rb) parent.set(rb, ra);
    }

    const groups = new Map();
    for (const word of parent.keys()) {
        const root = find(word);
        if (!groups.has(root)) groups.set(root, []);
        groups.get(root).push(word);
    }
    for (const words of groups.values()) words.sort();

    const options = text.split(" ").map(word =>
        parent.has(word) ? groups.get(find(word)) : [word]
    );

    const result = [];
    const path = [];

    function dfs(index) {
        if (index === options.length) {
            result.push(path.join(" "));
            return;
        }
        for (const choice of options[index]) {
            path.push(choice);
            dfs(index + 1);
            path.pop();
        }
    }

    dfs(0);
    result.sort();
    return result;
}

